// Shape Dashboard Data
// Turns the Google Sheet tabs into one small JSON file for the Lovable dashboard.
const ranges = $json.valueRanges || [];
const tab = (name) => {
  const r = ranges.find(v => String(v.range || '').replace(/'/g, '').split('!')[0] === name);
  return (r && r.values) || [];
};
const toIso = (v) => typeof v === 'number' ? new Date((Math.round(v) - 25569) * 864e5).toISOString().slice(0, 10) : String(v || '').slice(0, 10);
const rows = (t) => {
  const v = tab(t);
  const h = (v[0] || []).map(String);
  return v.slice(1).filter(r => r.some(x => x !== '' && x !== null && x !== undefined))
    .map(r => Object.fromEntries(h.map((k, i) => [k, r[i] === undefined ? '' : r[i]])));
};
const num = (x) => Number(x) || 0;
const wl = rows('Watchlist').filter(r => r.customer);
const customers = wl.map(r => ({
  customer: String(r.customer), status: String(r.status), usual_gap_days: num(r.usual_gap_days),
  days_silent: num(r.days_silent), last_order: toIso(r.last_order), orders: num(r.orders),
  yearly_value_rs: num(r.yearly_value_rs), at_risk_rs: num(r.at_risk_rs),
  likely_reason: String(r.likely_reason || ''), message: String(r.message || ''), decision: String(r.decision || '')
}));
const count = (s) => customers.filter(c => c.status === s).length;
const STATUSES = ['Gone Quiet', 'Slipping', 'Watch', 'Won Back', 'Seasonal', 'Healthy', 'Too New'];
const totals = {
  customers: customers.length,
  at_risk_rs: customers.reduce((a, c) => a + c.at_risk_rs, 0),
  won_back_rs: customers.filter(c => c.status === 'Won Back').reduce((a, c) => a + c.yearly_value_rs, 0),
  slipping: count('Slipping'), gone_quiet: count('Gone Quiet'), watch: count('Watch'),
  won_back: count('Won Back'), seasonal: count('Seasonal'), healthy: count('Healthy'), too_new: count('Too New')
};
const status_counts = STATUSES.map(s => ({ status: s, count: count(s) }));
const trend = rows('Run Log').map(r => ({ week: toIso(r.run_date), at_risk_rs: num(r.at_risk_rs), needs_action: num(r.needs_action) }))
  .filter(r => r.week).sort((a, b) => (a.week < b.week ? -1 : 1));
const action_list = customers.filter(c => ['Slipping', 'Gone Quiet', 'Watch', 'Won Back'].includes(c.status))
  .sort((a, b) => (b.at_risk_rs - a.at_risk_rs) || (b.yearly_value_rs - a.yearly_value_rs));
const decisions = rows('Decisions').filter(r => r.customer)
  .map(r => ({ customer: String(r.customer), decision: String(r.decision), date: toIso(r.date) })).reverse().slice(0, 15);
const rules = Object.fromEntries(tab('Rules').slice(1).map(r => [String(r[0]), r[1]]));
return [{ json: {
  business: String(rules.business_name || 'Your business'),
  updated_on: wl.length ? toIso(wl[0].updated_on) : '',
  generated_at: new Date().toISOString(),
  totals, status_counts, trend, action_list, decisions
} }];
